import os, glob, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Available grids:", sorted(G.keys()))

# Check if shift_up works
for name in ['Demo pair 1', 'Test']:
    key = f"{name} pair 1" if name == 'Demo' else 'Test input'
    if key in G:
        grid = G[key]
        # Find non-6 cells (the "pattern")
        shifted = []
        for i in range(len(grid)-1):
            row = grid[i+1][:]
            if len(shifted) < len(grid):
                shifted.append(row.copy())

        print(f"\n{name} input shape: {len(grid)}x{len(grid[0])}")
        print(f"Non-6 cells in input:")
        for i, row in enumerate(grid):
            for j, v in enumerate(row):
                if v != 6:
                    print(f"  ({i},{j}): {v}")

