import os, re, json
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
with open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl', 'r') as f:
    content = f.read()

# Extract all messages with their type and content
messages = []
current_type = None
for line in content.split('\n'):
    if not line.strip():
        continue
    if line.startswith('{'):
        try:
            msg = json.loads(line)
            current_type = msg.get('type')
            messages.append((current_type, msg))
        except:
            pass

# Look for text messages containing grid data
text_messages = [(t, m) for t, m in messages if t == 'text']
for typ, msg in text_messages:
    content = msg.get('content', '')
    if any(x in content.lower() for x in ['demo', 'input', 'output', 'grid', '3 ', '6 ']):
        print(f"Found text message:\n{content[:500]}\n")
